fn print_str(x: Str) {
    trace("print_str(", x, ")")
}

fn trace(x: Str, y: Str, z: Str) {
    print_str("trace(")
    print_str(x)
    print_str(", ")
    print_str(y)
    print_str(", ")
    print_str(z)
    print_str(")\n")
}

fn push(v: Vec<Int>, x: Int) -> Vec<Int> {
    trace("push(", v, ", ", x, ")")
    let n = len(&v)
    let mut result = clone(&v)
    result = result.resize(n + 1)
    result.set(n, x)
    result
}

fn len(v: &Vec<Int>) -> Int {
    trace("len(", v, ")")
    v.len()
}

fn get(v: &Vec<Int>, i: Int) -> Option<Int> {
    trace("get(", v, ", ", i, ")")
    if i >= 0 && i < len(&v) {
        Some(v.get(i))
    } else {
        None
    }
}

fn range(a: Int, b: Int) -> Vec<Int> {
    trace("range(", a, ", ", b, ")")
    let n = b - a
    let mut result = vec()
    for i in 0 < n {
        result = push(result, a + i)
    }
    result
}

fn clone(x: &Int) -> Int {
    trace("clone(", x, ")")
    x.clone()
}

